=== FILE: skid_buffer.v ===
// skid_buffer: valid/ready register slice (skid buffer).
// Implements microarchitecture.md section 3 for interface_spec.md.
// Every output is a flop or the inverse of one; inputs reach only next state.
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer beat when two are held.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Next-state values.
    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    // Output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // Upstream transfer on this edge.
    wire s_fire = s_valid && !skid_valid;

    // Upstream ready is the inverse of a flop.
    assign s_ready = !skid_valid;

    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // Skid beat moves to the output register; s_ready is low,
                // so no input beat is taken on this edge.
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                m_valid_d = s_valid;
                m_data_d  = s_data;
            end
        end else if (s_fire) begin
            // Output stalled with one beat: catch the incoming beat.
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control flops: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data flops: no reset (undefined while their valid is low).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

endmodule

`default_nettype wire
=== END FILE ===
