// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
`timescale 1ns/1ps
`default_nettype none

module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg  [7:0] s_data;
    reg        m_ready;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0:0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    // Verdict bookkeeping.
    integer passed;
    integer failed;
    reg [8*64-1:0] nonce;

    // Queue model of up to two beats.
    integer   cnt;
    reg [7:0] q0;
    reg [7:0] q1;
    reg       model_known;
    integer   accepted;
    integer   delivered;
    integer   dropped;

    // Per-step temporaries.
    reg       s_fire;
    reg       m_fire;
    reg       stalled;
    reg [7:0] held;
    reg       sr8_b;
    reg       sr1_b;
    reg       mv8_b;
    reg       mv1_b;
    reg [7:0] md8_b;
    reg [0:0] md1_b;

    integer   i;
    integer   a0;
    integer   d0;
    reg [31:0] r;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task check(input cond, input [8*48-1:0] msg);
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL: %0s at t=%0t", msg, $time);
            end
        end
    endtask

    task check_outputs;
        begin
            if (model_known) begin
                check(m_valid8 === (cnt > 0), "w8 m_valid matches model");
                check(s_ready8 === (cnt < 2), "w8 s_ready matches model");
                check(m_valid1 === (cnt > 0), "w1 m_valid matches model");
                check(s_ready1 === (cnt < 2), "w1 s_ready matches model");
                if (cnt > 0) begin
                    check(m_data8 === q0, "w8 m_data is the oldest beat");
                    check(m_data1 === q0[0:0], "w1 m_data is the oldest beat");
                end
            end
        end
    endtask

    task check_steady(input [8*48-1:0] msg);
        begin
            check((s_ready8 === sr8_b) && (s_ready1 === sr1_b), msg);
            check((m_valid8 === mv8_b) && (m_valid1 === mv1_b) &&
                  (m_data8 === md8_b) && (m_data1 === md1_b), msg);
        end
    endtask

    // One clock cycle: check outputs, flip inputs within the cycle,
    // take the edge, update the model.
    task step;
        begin
            #2;
            check_outputs;
            if (model_known) begin
                sr8_b = s_ready8;
                sr1_b = s_ready1;
                mv8_b = m_valid8;
                mv1_b = m_valid1;
                md8_b = m_data8;
                md1_b = m_data1;
                m_ready = ~m_ready;
                s_valid = ~s_valid;
                s_data  = ~s_data;
                #1;
                check_steady("outputs steady while inputs flip");
                m_ready = ~m_ready;
                s_valid = ~s_valid;
                s_data  = ~s_data;
                #1;
                check_steady("outputs steady after inputs restored");
            end
            s_fire  = s_valid && (cnt < 2);
            m_fire  = m_ready && (cnt > 0);
            stalled = !m_ready && (cnt > 0);
            held    = q0;
            @(posedge clk);
            #1;
            if (!rst_n) begin
                if (model_known) dropped = dropped + cnt;
                cnt = 0;
                model_known = 1'b1;
            end else begin
                if (m_fire) begin
                    q0 = q1;
                    cnt = cnt - 1;
                    delivered = delivered + 1;
                end
                if (s_fire) begin
                    if (cnt == 0) q0 = s_data;
                    else q1 = s_data;
                    cnt = cnt + 1;
                    accepted = accepted + 1;
                end
                if (stalled && model_known) begin
                    check((m_valid8 === 1'b1) && (m_data8 === held) &&
                          (m_valid1 === 1'b1) && (m_data1 === held[0:0]),
                          "hold: stalled beat stays offered");
                end
            end
        end
    endtask

    initial begin
        passed      = 0;
        failed      = 0;
        cnt         = 0;
        q0          = 8'h00;
        q1          = 8'h00;
        model_known = 1'b0;
        accepted    = 0;
        delivered   = 0;
        dropped     = 0;
        rst_n       = 1'b0;
        s_valid     = 1'b0;
        s_data      = 8'h00;
        m_ready     = 1'b0;

        // ---- Reset values ----
        step;
        step;
        check((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "reset: m_valid low");
        check((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "reset: s_ready high");
        rst_n   = 1'b1;
        m_ready = 1'b1;
        step;

        // ---- One-cycle latency ----
        s_valid = 1'b1;
        s_data  = 8'hA5;
        m_ready = 1'b1;
        check((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "latency: not offered before accept");
        step;
        s_valid = 1'b0;
        check((m_valid8 === 1'b1) && (m_data8 === 8'hA5) && (m_data1 === 1'b1),
              "latency: offered after accept edge");
        step;
        check((cnt == 0) && (m_valid8 === 1'b0) && (m_valid1 === 1'b0),
              "latency: beat leaves exactly once");

        // ---- Full throughput ----
        a0 = accepted;
        d0 = delivered;
        m_ready = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            s_valid = 1'b1;
            s_data  = i[7:0];
            if (i > 0) begin
                check((m_valid8 === 1'b1) && (s_ready8 === 1'b1) &&
                      (m_valid1 === 1'b1) && (s_ready1 === 1'b1),
                      "throughput: in and out on every edge");
            end
            step;
        end
        check((accepted - a0) == 64, "throughput: 64 beats accepted");
        check((delivered - d0) == 63, "throughput: 63 beats out, no bubble");
        s_valid = 1'b0;
        step;
        check(cnt == 0, "throughput: stream drained");

        // ---- Stall with one held, then two held ----
        a0 = accepted;
        d0 = delivered;
        s_valid = 1'b1;
        s_data  = 8'h11;
        m_ready = 1'b0;
        step;
        s_data = 8'h22;
        check((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "stall: one held, second accepted");
        step;
        check(cnt == 2, "stall: two beats held");
        s_data = 8'h33;
        for (i = 0; i < 3; i = i + 1) begin
            check((s_ready8 === 1'b0) && (s_ready1 === 1'b0), "stall: two held, third refused");
            step;
        end
        check((accepted - a0) == 2, "stall: third beat not taken");

        // ---- Ready rises after the stall ----
        m_ready = 1'b1;
        s_data  = 8'h33;
        step;
        step;
        s_data = 8'h44;
        step;
        s_valid = 1'b0;
        step;
        check((accepted - a0) == 4, "release: four beats accepted");
        check((delivered - d0) == 4, "release: four beats out once");
        check((cnt == 0) && (m_valid8 === 1'b0) && (m_valid1 === 1'b0), "release: slice drained");

        // ---- Random traffic against the model ----
        for (i = 0; i < 3000; i = i + 1) begin
            r = $random;
            s_valid = r[0] | (i[9] & r[1]);
            m_ready = (r[2] | (~i[9] & r[3])) & ~(i[7:5] == 3'b101);
            s_data  = r[15:8];
            step;
        end
        s_valid = 1'b0;
        m_ready = 1'b1;
        step;
        step;
        step;
        check((cnt == 0) && (m_valid8 === 1'b0) && (m_valid1 === 1'b0), "random: ends in a drain");
        check((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "random: s_ready high when idle");
        check(accepted == (delivered + dropped), "random: every beat out once");

        // ---- Reset with beats held ----
        s_valid = 1'b1;
        m_ready = 1'b0;
        s_data  = 8'h5A;
        step;
        s_data = 8'hC3;
        step;
        check((cnt == 2) && (m_valid8 === 1'b1) && (s_ready8 === 1'b0), "reset: two beats held before");
        rst_n = 1'b0;
        step;
        check((m_valid8 === 1'b0) && (m_valid1 === 1'b0), "reset: held beats dropped");
        check((s_ready8 === 1'b1) && (s_ready1 === 1'b1), "reset: s_ready high after");
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        step;
        s_valid = 1'b1;
        s_data  = 8'h77;
        step;
        s_valid = 1'b0;
        check((m_valid8 === 1'b1) && (m_data8 === 8'h77) && (m_data1 === 1'b1),
              "reset: slice works after reset");
        step;
        step;
        check((cnt == 0) && (m_valid8 === 1'b0) && (m_valid1 === 1'b0), "reset: drained after reset");

        // ---- Scoreboard ----
        check(accepted == (delivered + dropped + cnt), "scoreboard: in = out + dropped");

        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {8*64{1'b0}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
